1	import fs from 'node:fs';
2	import path from 'node:path';
3	import crypto from 'node:crypto';
4	import {spawnSync} from 'node:child_process';
5	import {fileURLToPath} from 'node:url';
6	const base=path.dirname(fileURLToPath(import.meta.url));
7	const inside=(root,file)=>file.startsWith(root+path.sep);
8	export function createRunner(stage){
9	 const directory=path.resolve(stage);
10	 if(!inside(base,directory))throw Error('Command logs must stay inside this campaign');
11	 const commands=path.join(directory,'commands');fs.mkdirSync(commands,{recursive:true});
12	 const index=path.join(commands,'index.jsonl');
13	 function run(executable,args,label,{timeout=180000}={}){
14	  if(!/^[A-Za-z0-9_-]+$/.test(label))throw Error('Use an explicit command label');
15	  const stem=new Date().toISOString().replace(/[:.]/g,'-')+'-'+crypto.randomUUID()+'-'+label;
16	  const prefix=path.join(commands,stem),started=Date.now();
17	  const r=spawnSync(executable,args,{encoding:'buffer',windowsHide:true,timeout,maxBuffer:64*1024*1024});
18	  fs.writeFileSync(prefix+'.stdout.raw.txt',r.stdout??Buffer.alloc(0),{flag:'wx'});
19	  fs.writeFileSync(prefix+'.stderr.raw.txt',r.stderr??Buffer.alloc(0),{flag:'wx'});
20	  const record={label,executable,argv:args,cwd:process.cwd(),started_at:new Date(started).toISOString(),elapsed_ms:Date.now()-started,exit_code:r.status,signal:r.signal,error:r.error?.message,files:{stdout:prefix+'.stdout.raw.txt',stderr:prefix+'.stderr.raw.txt',metadata:prefix+'.json'}};
21	  fs.writeFileSync(prefix+'.json',JSON.stringify(record,null,2)+'\n',{flag:'wx'});
22	  fs.appendFileSync(index,JSON.stringify(record)+'\n');
23	  return {...record,stdout:(r.stdout??Buffer.alloc(0)).toString('utf8'),stderr:(r.stderr??Buffer.alloc(0)).toString('utf8')};
24	 }
25	 function last(label){
26	  const rows=fs.existsSync(index)?fs.readFileSync(index,'utf8').split(/\r?\n/).filter(Boolean).map(JSON.parse):[];
27	  const row=rows.findLast(x=>x.label===label);
28	  if(!row)throw Error(`No exact command label: ${label}`);
29	  return {...row,stdout:fs.readFileSync(row.files.stdout,'utf8'),stderr:fs.readFileSync(row.files.stderr,'utf8')};
30	 }
31	 function json(label){const r=last(label);if(r.exit_code!==0)throw Error(`Command ${label} exited ${r.exit_code}; see ${r.files.metadata}`);return JSON.parse(r.stdout.replace(/^\uFEFF/,''));}
32	 return {run,last,json,index};
33	}
